document.addEventListener("DOMContentLoaded",function(){const offcanvas=document.getElementById("offcanvas");if(!offcanvas){return;}
offcanvas.style.width="100vw";offcanvas.style.left="0";offcanvas.style.maxWidth="100vw";offcanvas.style.backgroundColor="#1a1a1a";});document.addEventListener("DOMContentLoaded",function(){const h3s=document.querySelectorAll(".page-about h3");const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("animate");}else{entry.target.classList.remove("animate");}});},{threshold:0.2});h3s.forEach(h3=>observer.observe(h3));});